function h(a,b,c){if(!c.includes(b))return 0;const d=(a,b,c)=>a.slice(0,b)+c+a.slice(b+1);const {length:e}=a;const m={};const f={};for(const x of[a,...c]){const r=[];for(let i=0;i<e;i++){const a=d(x,i,'*');r.push(a);f[a]??(f[a]=[]);f[a].push(x);}m[x]=r;}let r=0;let g=m[a];const s=new Set([a]);while(g.length){const a=[];r++;for(const x of g){for(const y of f[x]){if(y===b)return r+1;if(s.has(y))continue;s.add(y);a.push(...m[y]);}}g=a;}return 0;}function solve(a,b,c){return h(a,b,c);}
